<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
use Sentinel\Repositories\PermissionRepository;
final class PilotSetupService
{
    use TenantOperations;
    public const TEMPLATES=[
        'GUARD'=>['guard.self','alarm_response.self','guard_transport.self','post_orders.self','continuity.self','learning.self','stock.self','key_register.self','availability.self','shift_offers.self','fleet.self','workflow_languages.self','radio.self','customer_support.self','release_notices.view','users.password_change'],
        'CLIENT'=>['client_portal.read','extra_services.client','client_mobilisation.client','risk_assessments.client','client_reports.schedule','report_reviews.client','client_requests.client','quotations.client','service_reviews.client','visitor_invites.client','renewals.client','customer_support.self','release_notices.view','users.password_change'],
        'SITE_SUPERVISOR'=>['site_scope.restricted','alarm_response.view','alarm_response.manage','guard_transport.view','guard_transport.manage','post_orders.view','post_orders.manage','continuity.view','continuity.manage','equipment_checks.view','equipment_checks.manage','control_handover.view','control_handover.manage','extra_services.view','extra_services.manage','client_mobilisation.view','client_mobilisation.manage','risk_assessments.view','risk_assessments.manage','learning.view','learning.manage','lost_found.view','lost_found.manage','stock.view','stock.manage','investigations.view','investigations.manage','site_workspace.view','inspection_forms.view','inspection_forms.manage','key_register.view','key_register.manage','emergency_procedures.view','emergency_procedures.manage','radio.self','control_map.view','operational_alerts.view','visitor_invites.view','visitor_invites.manage','visitor_invites.gate','fleet.view','fleet.manage','shift_offers.view','shift_offers.manage','users.password_change'],
    ];
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly PermissionRepository $permissions,private readonly SubscriptionService $subscriptions,private readonly EncryptedBackupService $backups) {}
    public function overview():array {$checks=[];foreach(['open_shift_offers','visitor_appointments','fleet_vehicles','contract_renewals','encrypted_backups','pilot_role_templates']as$table){try{$this->db->fetch('SELECT company_id FROM '.$table.' WHERE company_id=:company LIMIT 1',['company'=>$this->company()]);$checks[]=['check'=>$table,'state'=>'PASS'];}catch(\PDOException){$checks[]=['check'=>$table,'state'=>'BLOCKED'];}}$backup=$this->backups->overview();$verified=array_values(array_filter(array_slice($backup['jobs'],0,1),fn($r)=>$r['state']==='READY'&&$r['restore_state']==='PASSED'&&$r['restored_at']>=gmdate('Y-m-d H:i:s',time()-7*86400)));$checks[]=['check'=>'Private encrypted backup configured','state'=>$backup['configured']?'PASS':'BLOCKED'];$checks[]=['check'=>'Data restore verified within seven days','state'=>$verified?'PASS':'BLOCKED'];$drill=$this->db->fetch("SELECT check_id FROM company_setup_checks WHERE company_id=:company AND check_code='BACKUP'",['company'=>$this->company()]);$checks[]=['check'=>'Production-database restore drill evidence recorded','state'=>$drill?'PASS':'BLOCKED'];$settings=$this->db->fetch('SELECT reminder_user_id,revision FROM business_operation_settings WHERE company_id=:company',['company'=>$this->company()]);$checks[]=['check'=>'Reminder supervisor selected','state'=>$settings?'PASS':'BLOCKED'];$templates=$this->db->fetchAll('SELECT template_code,role_id FROM pilot_role_templates WHERE company_id=:company',['company'=>$this->company()]);$checks[]=['check'=>'Role templates created (assign users separately)','state'=>count($templates)>=3?'PASS':'BLOCKED'];$workers=[];foreach(['operations-hub','business-operations','backups']as$name){$w=$this->db->fetch('SELECT finished_at,state FROM worker_runs WHERE company_id=:company AND worker_name=:name ORDER BY run_id DESC LIMIT 1',['company'=>$this->company(),'name'=>$name]);$workers[]=['worker'=>$name,'state'=>$w===null?'UNKNOWN':($w['state']!=='OK'?'FAILED':($w['finished_at']<gmdate('Y-m-d H:i:s',time()-($name==='backups'?172800:300))?'STALE':'OK')),'last_receipt'=>$w['finished_at']??null];}return ['checks'=>$checks,'technical_checks_passed'=>!array_filter($checks,fn($r)=>$r['state']!=='PASS')&&!array_filter($workers,fn($r)=>$r['state']!=='OK'),'roles'=>$templates,'templates'=>array_keys(self::TEMPLATES),'settings'=>$settings,'workers'=>$workers,'demo_records'=>$this->db->fetchAll('SELECT * FROM pilot_demo_records WHERE company_id=:company ORDER BY demo_id',['company'=>$this->company()]),'note'=>'These checks support a supervised pilot. Assign users, site grants and client mappings explicitly; complete company acceptance evidence and test real phones, receivers and response procedures before live use. Demonstrations never enter operational records.'];}
    public function role(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['template_code']);if(!$this->context->mfaVerified()||!$this->permissions->userHasPermission($this->actor(),'roles.create')||!$this->permissions->userHasPermission($this->actor(),'roles.assign_permissions'))throw HttpException::forbidden('Role templates require an MFA-verified role administrator.');$code=$input['template_code']??null;if(!is_string($code)||!isset(self::TEMPLATES[$code]))throw HttpException::unprocessable('Choose a known role template.');$old=$this->db->fetch('SELECT role_id FROM pilot_role_templates WHERE company_id=:company AND template_code=:code',['company'=>$this->company(),'code'=>$code]);if($old)return ['role_id'=>(string)$old['role_id'],'created'=>false];$this->db->execute("INSERT INTO roles(company_id,role_name,role_description,is_system_role,status) VALUES(:company,:name,:description,0,'ACTIVE')",['company'=>$this->company(),'name'=>'Pilot '.str_replace('_',' ',ucwords(strtolower($code),'_')),'description'=>'Pilot template; explicitly assign user memberships and site/client access.']);$role=(string)$this->db->connection()->lastInsertId();$granted=[];$skipped=[];foreach(self::TEMPLATES[$code]as$p){$permission=$this->db->fetch("SELECT permission_id FROM permissions WHERE company_id=:company AND permission_code=:code AND status='ACTIVE'",['company'=>$this->company(),'code'=>$p]);if(!$permission||!$this->subscriptions->allows($p)){$skipped[]=$p;continue;}$this->db->execute('INSERT INTO role_permissions(company_id,role_id,permission_id) VALUES(:company,:role,:permission)',['company'=>$this->company(),'role'=>$role,'permission'=>$permission['permission_id']]);$granted[]=$p;}if($code==='SITE_SUPERVISOR'&&!in_array('site_scope.restricted',$granted,true))throw HttpException::unprocessable('Seed the site restriction marker before creating this template.');$this->db->execute('INSERT INTO pilot_role_templates(company_id,template_code,role_id) VALUES(:company,:code,:role)',['company'=>$this->company(),'code'=>$code,'role'=>$role]);$this->audit->record('pilot_role_template','created',$role,[],[],['code'=>$code,'permissions'=>$granted]);return ['role_id'=>$role,'granted'=>$granted,'skipped'=>$skipped,'note'=>'No users were automatically assigned this role.'];});}
    public function settings(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['reminder_user_id','expected_revision']);$user=$this->row('users','user_id',$input['reminder_user_id']??null);$id=(string)$user['user_id'];if($user['status']!=='ACTIVE'||!$this->permissions->userHasPermission($id,'pilot_setup.view')||$this->permissions->userHasPermission($id,'site_scope.restricted'))throw HttpException::unprocessable('Choose an active unrestricted supervisor with pilot setup access.');$old=$this->db->fetch('SELECT revision FROM business_operation_settings WHERE company_id=:company',['company'=>$this->company()]);if($this->number($input['expected_revision']??null,0)!==(int)($old['revision']??0))throw HttpException::conflict('Supervisor setting changed.');if($old)$this->db->execute('UPDATE business_operation_settings SET reminder_user_id=:user,revision=revision+1 WHERE company_id=:company',['company'=>$this->company(),'user'=>$id]);else $this->db->execute('INSERT INTO business_operation_settings(company_id,reminder_user_id) VALUES(:company,:user)',['company'=>$this->company(),'user'=>$id]);$this->audit->record('business_settings','saved',(string)$this->company());return ['saved'=>true];});}
    public function demo():array {return $this->atomic(function(){$old=$this->db->fetch('SELECT demo_id FROM pilot_demo_records WHERE company_id=:company',['company'=>$this->company()]);if($old)return ['id'=>(string)$old['demo_id']];$examples=['classification'=>'DEMONSTRATION ONLY — not operational data','shift_offer'=>['guard'=>'Demo Guard','state'=>'ACCEPTED — manager approval required'],'visitor'=>['name'=>'Demo Visitor','state'=>'PENDING — client approval required'],'fleet'=>['registration'=>'DEMO-ONLY','pre_trip'=>'Inspect brakes, tyres, lights, seatbelts and fluids'],'renewal'=>['currency'=>'ZAR','monthly_minor'=>100000,'state'=>'EXAMPLE — not a contract']];$this->db->execute('INSERT INTO pilot_demo_records(company_id,label,scenario_json,created_by_user_id,created_at) VALUES(:company,:label,:json,:actor,:now)',['company'=>$this->company(),'label'=>'DEMONSTRATION ONLY — supervised pilot examples','json'=>json_encode($examples,JSON_THROW_ON_ERROR),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('pilot_demo');});}
}
